<?php
require_once __DIR__.'/../includes/functions.php'; require_admin(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='category'){ $name=trim($_POST['category_name']??''); if($name!==''){ $st=$pdo->prepare('INSERT INTO business_categories(name,slug) VALUES(?,?)');$st->execute([$name,unique_slug($pdo,'business_categories',$name)]);flash('Category added.');} }
 if($action==='save'){ $id=(int)($_POST['id']??0);$name=trim($_POST['business_name']??''); if($name===''){flash('Business name is required.');}else{$data=[(int)($_POST['category_id']??0)?:null,$name,trim($_POST['description']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),trim($_POST['email']??''),trim($_POST['address']??''),trim($_POST['city']??'Jos'),trim($_POST['website']??''),$_POST['status']??'pending'];if($id){$slug=unique_slug($pdo,'businesses',$name,$id);$q=$pdo->prepare('UPDATE businesses SET category_id=?,business_name=?,slug=?,description=?,phone=?,whatsapp=?,email=?,address=?,city=?,website=?,status=? WHERE id=?');$q->execute([$data[0],$name,$slug,$data[2],$data[3],$data[4],$data[5],$data[6],$data[7],$data[8],$data[9],$id]);}else{$slug=unique_slug($pdo,'businesses',$name);$q=$pdo->prepare('INSERT INTO businesses(category_id,business_name,slug,description,phone,whatsapp,email,address,city,website,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$data[0],$name,$slug,$data[2],$data[3],$data[4],$data[5],$data[6],$data[7],$data[8],$data[9]]);}flash('Business listing saved.');}}
 if($action==='delete'){ $q=$pdo->prepare('DELETE FROM businesses WHERE id=?');$q->execute([(int)$_POST['id']]);flash('Business listing deleted.');} header('Location: businesses.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM businesses WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$cats=$pdo->query('SELECT * FROM business_categories ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT b.*,c.name category FROM businesses b LEFT JOIN business_categories c ON c.id=b.category_id ORDER BY b.created_at DESC')->fetchAll();$pageTitle='Business listings';include __DIR__.'/_header.php'; ?>
<div class="dash-top"><div><span class="eyebrow">Business directory</span><h1>Business listings</h1><p>Add, edit, approve or reject directory entries.</p></div></div>
<div class="admin-two-col"><section class="dash-panel"><h2><?= $edit?'Edit listing':'Add a business'?></h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Business name<input name="business_name" required value="<?=e($edit['business_name']??'')?>"></label><label>Category<select name="category_id"><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Description<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><div class="form-row"><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>WhatsApp<input name="whatsapp" value="<?=e($edit['whatsapp']??'')?>"></label></div><div class="form-row"><label>Email<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Website<input name="website" value="<?=e($edit['website']??'')?>"></label></div><label>Address<input name="address" value="<?=e($edit['address']??'')?>"></label><div class="form-row"><label>City<input name="city" value="<?=e($edit['city']??'Jos')?>"></label><label>Status<select name="status"><?php foreach(['pending','approved','rejected'] as $s):?><option <?=$s===($edit['status']??'pending')?'selected':''?>><?=$s?></option><?php endforeach;?></select></label></div><button class="btn">Save listing</button> <?php if($edit):?><a class="btn btn-outline" href="businesses.php">Cancel</a><?php endif;?></form></section>
<section class="dash-panel"><h2>Business categories</h2><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="category"><input name="category_name" placeholder="e.g. Food &amp; Catering" required><button class="btn">Add</button></form><div class="tag-list"><?php foreach($cats as $c):?><span><?=e($c['name'])?></span><?php endforeach;?></div></section></div>
<section class="dash-panel"><h2>All listings (<?=count($rows)?>)</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Business</th><th>Category</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['business_name'])?></strong><small><?=e($r['phone'])?></small></td><td><?=e($r['category']??'Uncategorised')?></td><td><?=e($r['city'])?></td><td><span class="status status-<?=e($r['status'])?>"><?=e($r['status'])?></span></td><td class="actions"><a href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this listing?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No business listings yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php include __DIR__.'/_footer.php'; ?>